const S = require("spatial");

const scene = new S.Scene();
const marker = new S.Mesh(new S.BoxGeometry(0.1, 0.1, 0.1), new S.MeshStandardMaterial());
marker.name = "marker";
scene.add(marker);

scene.userData.hookRan = false;
scene.userData.restored = null;

// SPEC 14.10: called after load and before the first frame, with the state
// the previous script held.
this.scriptChanged = (previous) => {
  scene.userData.hookRan = true;
  scene.userData.restored = previous;
  this.state = previous;
};

S.mount(scene);
